const CACHE='salati-shell-v131';const ASSETS=['./','./index.html','./privacy.html','./style.css','./light-theme.css','./salati-design.css','./app-v1.0.97.js','./icon.svg','./icon-192.png','./icon-512.png','./manifest.json','./fonts/Cairo-Variable.ttf','./fonts/AmiriQuran-Regular.ttf','./fonts/MadinahHafsClassic.ttf','./quran/data.json','./images/mosque.webp','./images/salati-brand.png','./icons/navigation.svg','./icons/clock.svg','./icons/gear.svg','./icons/moon.svg','./icons/moon-stars.svg','./icons/sun.svg','./icons/sunrise.svg','./icons/sunset.svg'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>(k.startsWith('salati-shell-')||k==='salati-v1')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==location.origin||(u.pathname.includes('/audio/')||u.pathname.includes('/downloads/')))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&r.status===200){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
